// Get the incoming data
const expenses = $input.first().json.expenses;
const departmentName = $input.first().json.department_name;

// 1. Summarize Expenses
let totalPendingAmount = 0;
let expenseCountByUser = {};
let weekendSubmissions = 0;
const today = new Date();

for (const expense of expenses) {
  if (expense.status === 'pending') {
    totalPendingAmount += expense.amount;
  }

  // Count submissions by user
  const userName = expense.user.name;
  expenseCountByUser[userName] = (expenseCountByUser[userName] || 0) + 1;

  // Check for weekend submissions
  const submissionDate = new Date(expense.created_at);
  const dayOfWeek = submissionDate.getDay();
  if (dayOfWeek === 0 || dayOfWeek === 6) {
    weekendSubmissions++;
  }
}

// 2. Create the final summary object
const summary = {
  departmentName: departmentName,
  totalRecentExpenses: expenses.length,
  totalPendingAmount: totalPendingAmount,
  submissionsByUser: expenseCountByUser,
  weekendSubmissions: weekendSubmissions,
  spendingByCategory: $input.item.json.spending_by_category
};

// Return this summary for the next node
return { summary: summary };

